def create_policy_drafts(apps, schema_editor):
    LegalPage = apps.get_model("website", "LegalPage")
    LegalSection = apps.get_model("website", "LegalSection")
    database = schema_editor.connection.alias
    for slug, content in INITIAL_POLICY_DRAFTS.items():
        page = LegalPage.objects.using(database).create(
            slug=slug, title=content["title"], introduction=content["introduction"],
            approved_for_publication=False,
        )
        for index, (title, body) in enumerate(content["sections"]):
            LegalSection.objects.using(database).create(page=page, title=title, body=body, sort_order=index)


